/* BettorToken Command: isolated, dependency-free, read-only application. */
(function(){
'use strict';
const C=window.BTCore, cfg=window.BETTOR_COMMAND_CONFIG||{};
const root=document.getElementById('app'),overlayRoot=document.getElementById('overlay-root');
const icons={
 command:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',
 portfolio:'M3 7h18v14H3z M8 7V3h8v4 M3 12h18 M10 12v3h4v-3',
 orders:'M6 3h12v18H6z M9 7h6 M9 11h6 M9 15h3',
 decisions:'M8 3h8v4h-8z M8 17h8v4h-8z M3 10h5v4H3z M16 10h5v4h-5z M12 7v3 M5.5 10V8h13v2 M5.5 14v2h13v-2 M12 16v1',
 risk:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M9 12l2 2 4-5',
 models:'M8 4h8v4h4v8h-4v4H8v-4H4V8h4z M9 9h6v6H9z',
 reports:'M5 3h10l4 4v14H5z M15 3v5h4 M8 12h8 M8 16h8',
 audit:'M5 4h14v17H5z M9 4V2h6v2 M9 9h6 M9 13h6 M9 17h4',
 investor:'M3 20h18 M5 20v-9 M10 20v-9 M14 20v-9 M19 20v-9 M3 8l9-5 9 5z',
 search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 M15 15l6 6',
 chevron:'M9 5l7 7-7 7', down:'M6 9l6 6 6-6', arrow:'M5 12h14 M13 6l6 6-6 6',up:'M5 16l11-11 M5 5h11v11',
 download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',
 close:'M5 5l14 14 M19 5L5 19',menu:'M3 6h18 M3 12h18 M3 18h18',
 clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',
 calendar:'M4 5h16v16H4z M4 10h16 M8 3v4 M16 3v4',
 pause:'M8 5v14 M16 5v14',play:'M7 4l14 8-14 8z',refresh:'M20 10a8 8 0 1 0-1 7 M20 3v7h-7',
 bell:'M6 9a6 6 0 0 1 12 0v6l2 3H4l2-3z M10 21h4',
 link:'M9 15l6-6 M9 7l3-3a5 5 0 0 1 7 7l-3 3 M15 17l-3 3a5 5 0 0 1-7-7l3-3',
 shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M12 8v5 M12 16v.01',
 lock:'M5 10h14v11H5z M8 10V7a4 4 0 0 1 8 0v3',
 eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z M9 12a3 3 0 1 0 6 0 3 3 0 0 0-6 0',
 activity:'M2 12h5l3-8 4 16 3-8h5',check:'M5 12l4 4L19 6',info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 10v7 M12 7v.01',
 filter:'M3 5h18 M6 12h12 M9 19h6',copy:'M8 8h13v13H8z M16 8V3H3v13h5',
 terminal:'M4 6l5 6-5 6 M12 18h8',bolt:'M13 2L4 14h7l-1 8L20 9h-7z',globe:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M3 12h18 M12 3c-5 5-5 13 0 18 M12 3c5 5 5 13 0 18',file:'M5 3h10l4 4v14H5z M15 3v5h4',external:'M14 3h7v7 M21 3L10 14 M10 5H3v16h16v-7'};
const icon=(name,size=16)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.command}"/></svg>`;
const nav=[['command','Overview'],['portfolio','Portfolio'],['orders','Orders'],['decisions','EV decisions'],['risk','Risk & exposure'],['models','Intelligence'],['reports','Reporting'],['audit','Audit trail'],['investor','Investor briefing']];
const S={view:'command',snapshot:null,connection:'disconnected',error:null,mode:'offline',period:'MTD',query:'',filter:'ALL',menu:false,frozen:false,pending:null,playback:false,step:0,exports:[],lastFocus:null};
const pill=(str,tone='')=>`<span class="pill ${tone}"><i class="dot"></i>${C.esc(str)}</span>`;
const tone=v=>!C.finite(v)?'':v>0?'positive':v<0?'negative':'';
const stateTone=x=>['PASS','FILLED','HOLD'].includes(x)?'green':['BLOCKED','REJECTED','EXIT WATCH'].includes(x)?'amber':['PARTIAL','SHADOW','PASSIVE EXIT'].includes(x)?'blue':'';
const btn=(label,action,ico,cls='',attrs='')=>`<button type="button" class="button ${cls}" data-action="${action}" ${attrs}>${ico?icon(ico):''}${label}</button>`;
const titleFor=v=>(nav.find(n=>n[0]===v)||nav[0])[1];
function activeData(){return S.view==='investor'&&S.snapshot?.mode==='DEMO'?C.projectInvestor(S.snapshot):S.snapshot;}
function current(){return activeData();}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('toast-visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('toast-visible'),4200);}
const feed=new C.Feed(cfg,update=>{
 S.connection=update.status;S.error=update.error||null;
 // An auth refusal or audience reset must clear even a frozen display.
 if(!update.snapshot){S.snapshot=null;S.pending=null;S.frozen=false;S.exports=[];closeOverlay();render();return;}
 if(S.frozen){S.pending=update.snapshot;updateClock();return;}
 S.snapshot=update.snapshot;render();
});
function sourceBadge(){if(S.mode==='demo')return pill('DEMO DATA','amber');const f=C.freshness(S.snapshot,Date.now(),cfg.staleMs,S.connection);return pill(S.frozen?'VIEW FROZEN':f.status,f.status==='LIVE'?'green':f.status==='SHADOW'?'blue':f.status==='STALE'?'amber':'');}
function sidebar(){return `<aside class="sidebar" aria-label="Command navigation"><a class="brand" href="#command" aria-label="BettorToken Command"><img src="${C.esc(cfg.logo)}" alt="Bettor Token — Tokenized Asset Management"><div class="brand-sub">C O M M A N D</div></a><div class="workspace"><div class="workspace-icon">${icon('investor',16)}</div><div><div class="workspace-title">Institutional workspace</div><small>READ-ONLY OBSERVATION</small></div></div><div class="nav-title">OPERATIONS</div><nav class="nav">${nav.slice(0,6).map(([id,label])=>navItem(id,label)).join('')}</nav><div class="nav-section"><div class="nav-title">GOVERNANCE</div><nav class="nav">${nav.slice(6).map(([id,label])=>navItem(id,label)).join('')}</nav></div><div class="sidebar-bottom"><div class="system-mini"><div class="flex between"><span class="label">Execution authority</span>${icon('lock',12)}</div><div class="line"><span>Order submission</span><span class="amber">DISABLED</span></div><div class="line"><span>Auto promotion</span><span>OFF</span></div><button class="text-button" style="margin-top:11px" data-action="connection">Connection settings ${icon('arrow',12)}</button></div><button class="user selectable-row" data-action="profile"><span class="avatar">BT</span><span><strong>Workspace observer</strong><small>Institutional preview</small></span><span style="margin-left:auto">${icon('down',12)}</span></button></div></aside>`;}
function navItem(id,label){const n=id==='orders'?S.snapshot?.orders?.filter(o=>['RESTING','PARTIAL'].includes(o.status)).length:id==='portfolio'?S.snapshot?.positions?.length:null;return `<button data-view="${id}" class="${S.view===id?'active':''}" ${S.view===id?'aria-current="page"':''}>${icon(id,17)}<span>${label}</span>${n?`<span class="nav-count">${n}</span>`:''}</button>`;}
function banner(){if(S.mode==='demo')return `<div class="mode-banner"><div><span class="banner-label">DESIGN PREVIEW</span>Illustrative data only.<span class="banner-detail"> Not BettorToken performance. No live orders.</span></div><button data-action="exitDemo" class="text-button">Exit demo ${icon('arrow',11)}</button></div>`;
 if(S.error)return `<div class="mode-banner red-banner"><div><span class="banner-label">FEED UNAVAILABLE</span>${C.esc(S.error)} ${S.snapshot?'Last snapshot retained; not current.':'No portfolio data loaded.'}</div><button class="text-button" data-action="connection">Details</button></div>`;
 if(S.frozen)return `<div class="mode-banner"><div><span class="banner-label">VIEW FROZEN</span>Only this display is paused. This is not an execution control.</div><button class="text-button" data-action="freeze">Resume view</button></div>`;
 if(!S.snapshot)return `<div class="mode-banner blue-banner"><div><span class="banner-label">READ-ONLY WORKSPACE</span>No live source connected. Financial values remain unavailable.</div><button class="text-button" data-action="demo">Explore demo ${icon('arrow',11)}</button></div>`;
 const f=C.freshness(S.snapshot,Date.now(),cfg.staleMs,S.connection);return `<div class="mode-banner ${f.status==='STALE'?'':'blue-banner'}"><div><span class="banner-label">${C.esc(f.status)}</span>${C.esc(S.snapshot.source)} · as of ${C.esc(S.snapshot.asOf)}. No order authority.</div><button class="text-button" data-action="connection">Source details</button></div>`;}
function render(){document.body.dataset.context=S.mode==='demo'?'DEMO — ILLUSTRATIVE DATA ONLY':S.snapshot?.mode||'DISCONNECTED';root.innerHTML=`<div class="shell ${S.menu?'menu-open':''}"><button class="mobile-shade" data-action="menu" aria-label="Close navigation"></button>${sidebar()}<div class="main-shell"><header class="topbar"><button class="icon-button mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu',20)}</button><img class="mobile-brand" src="${C.esc(cfg.logo)}" alt="BettorToken"><div class="breadcrumbs"><span>BettorToken</span><span class="slash">/</span><strong>${C.esc(titleFor(S.view))}</strong></div><button class="search-button" data-action="search">${icon('search',15)}<span class="search-label">Search the workspace</span><kbd>⌘ K</kbd></button><div class="grow"></div><span id="top-clock" class="top-clock"></span><span class="topbar-divider"></span><span id="source-badge">${sourceBadge()}</span><button class="icon-button" data-action="alerts" aria-label="System notifications">${icon('bell',17)}</button></header><main class="main-content"><div id="mode-banner">${banner()}</div><div id="pagebody" tabindex="-1">${viewContent()}</div><footer class="bottom-status"><div class="flex">${icon('lock',10)}READ ONLY<span class="divider">/</span><span>${S.mode==='demo'?'SYNTHETIC DESIGN FIXTURE':'NO ORDER SUBMISSION PATH'}</span></div><div><span class="watermark">${S.mode==='demo'?'DEMONSTRATION · NOT PERFORMANCE':'INTERNAL WORKSPACE'}</span><span class="divider">/</span>COMMAND <span class="motion-build">MOTION EDITION / 1.1</span></div></footer></main></div></div>`;updateClock();bindChart();window.BTMotion?.mount({mode:S.mode,view:S.view,snapshot:current(),frozen:S.frozen,connection:S.connection});}
function heading(title,subtitle){return `<div class="page-heading"><div><div class="page-meta"><span>BETTORTOKEN COMMAND</span><span> / </span><span>${S.snapshot?C.date(S.snapshot.asOf).toUpperCase():'AWAITING CONNECTION'}</span></div><h1>${C.esc(title)}</h1><p>${C.esc(subtitle)}</p></div><div class="heading-actions">${btn(S.snapshot?C.date(S.snapshot.asOf):'Snapshot','source','calendar','ghost date-button')}${btn(S.frozen?'Resume view':'Freeze view','freeze',S.frozen?'play':'pause','ghost freeze-button',!S.snapshot?'disabled':'')}${btn('Generate report','report','download','primary',!S.snapshot?'disabled':'')}</div></div>`;}
function empty(title='Connect your institutional workspace',desc='Connect the read-only aggregation service to see actual balances, positions, standing orders and engine decisions. Unavailable is never shown as zero.'){return `<div class="panel empty"><div class="empty-icon">${icon('link',23)}</div><h2>${title}</h2><p>${desc}</p><div class="empty-actions">${btn('Connection setup','connection','link','primary')}${btn('Explore design preview','demo','play','ghost')}</div></div>`;}
function noRows(label){return `<div class="empty" style="padding:28px 15px"><p>${C.esc(label)}</p></div>`;}
function miniBars(green=false){return `<span class="mini-bars ${green?'green':''}" aria-hidden="true">${[8,13,11,16,12,19,15,22].map(h=>`<i style="height:${h}px"></i>`).join('')}</span>`;}
function kpis(){const s=current(),a=s?.account;return `<div class="kpis"><div class="kpi"><div class="kpi-top"><span class="label">Net P&L · MTD</span>${icon('activity',14)}</div><div class="kpi-value ${tone(a?.netMtd)}">${C.signed(a?.netMtd)}</div><div class="kpi-note">Realized + unrealized<span class="badge-label">${s?'Source-window economics':'Not connected'}</span></div>${s?miniBars(true):''}</div><div class="kpi"><div class="kpi-top"><span class="label">Unrealized P&L</span>${icon('portfolio',14)}</div><div class="kpi-value ${tone(a?.unrealized)}">${C.signed(a?.unrealized)}</div><div class="kpi-note">${s?C.count(s.counts?.positions??s.positions.length):'—'} open positions · marked value</div></div><div class="kpi"><div class="kpi-top"><span class="label">Available capital</span>${icon('investor',14)}</div><div class="kpi-value">${C.usd(a?.available)}</div><div class="kpi-note">Cash less reserved capital</div></div><div class="kpi"><div class="kpi-top"><span class="label">Standing orders</span>${icon('orders',14)}</div><div class="kpi-value">${s?C.count(s.counts?.orders??s.orders.filter(o=>['RESTING','PARTIAL'].includes(o.status)).length):'—'}<small style="font:11px var(--sans);color:var(--muted);letter-spacing:0;margin-left:10px">${s?.audience==='INTERNAL'?s.orders.filter(o=>o.status==='PARTIAL').length+' partial':''}</small></div><div class="kpi-note">Venue-acknowledged status${s?.mode==='DEMO'?' · illustrative':''}</div>${s?miniBars():''}</div></div>`;}
function plot(){const s=current();if(!s?.history?.length)return '<div class="chart-empty">No portfolio history supplied</div>';let h=s.history;const last=Date.parse(s.asOf),days=S.period==='1D'?1:S.period==='1W'?7:40;h=h.filter(p=>last-Date.parse(p.at)<=days*86400000);if(h.length<2)return '<div class="chart-empty">Insufficient history at this window</div>';const W=780,H=218,left=3,right=65,top=18,bottom=25;const vals=h.map(p=>p.value),lo=Math.min(...vals),hi=Math.max(...vals),pad=Math.max((hi-lo)*.15,1),mn=lo-pad,mx=hi+pad;const pts=h.map((p,i)=>({x:left+i/(h.length-1)*(W-left-right),y:top+(mx-p.value)/(mx-mn)*(H-top-bottom),p}));const path=pts.map((p,i)=>`${i?'L':'M'}${p.x.toFixed(2)},${p.y.toFixed(2)}`).join(' ');const fill=path+` L${pts.at(-1).x},${H-bottom} L${left},${H-bottom}Z`;const end=pts.at(-1);const ylines=Array.from({length:4},(_,i)=>{const y=top+i*(H-top-bottom)/3;return `<line x1="${left}" x2="${W-right}" y1="${y}" y2="${y}" stroke="#243148" stroke-dasharray="3 5"/><text x="${W-right+14}" y="${y+3}" fill="#6b829f" font-size="9" font-family="monospace">${(mx-i*(mx-mn)/3>=1e6)?('$'+((mx-i*(mx-mn)/3)/1e6).toFixed(3)+'m'):C.usd(mx-i*(mx-mn)/3)}</text>`;}).join('');const dates=[0,Math.floor((h.length-1)*.25),Math.floor((h.length-1)*.5),Math.floor((h.length-1)*.75),h.length-1].map((j,i)=>`<text x="${pts[j].x}" y="${H-2}" fill="#6882a3" font-size="9" text-anchor="${i===0?'start':i===4?'end':'middle'}">${S.period==='1D'?C.clock(h[j].at).slice(0,5):C.date(h[j].at).split(',')[0]}</text>`).join('');return `<div class="chart-wrap" data-chart="portfolio"><div id="chart-tooltip" class="chart-tooltip"></div><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${s.mode==='DEMO'?'Illustrative ':''}portfolio value during ${S.period}. Ending ${C.usd(end.p.value)}"><defs><linearGradient id="curve-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#1d78f9" stop-opacity=".25"/><stop offset="100%" stop-color="#1d78f9" stop-opacity=".01"/></linearGradient></defs>${ylines}<path d="${fill}" fill="url(#curve-fill)"/><path d="${path}" fill="none" stroke="#4f9aff" stroke-width="2.2" stroke-linejoin="round"/><circle cx="${end.x}" cy="${end.y}" r="7" fill="#3387ff22"/><circle cx="${end.x}" cy="${end.y}" r="3" fill="#87beff"/>${dates}${pts.map(p=>`<circle class="chart-hit" cx="${p.x}" cy="${p.y}" r="9" fill="transparent" data-value="${p.p.value}" data-at="${C.esc(p.p.at)}"/>`).join('')}</svg></div>`;}
function portfolioChart(){const s=current(),a=s?.account;return `<section class="panel"><div class="panel-head"><div><h2>Portfolio value</h2><div class="panel-sub">Account snapshot · not Company or token NAV</div></div><div class="segmented" aria-label="Chart period">${['1D','1W','MTD'].map(x=>`<button data-period="${x}" class="${S.period===x?'on':''}" aria-pressed="${S.period===x}">${x}</button>`).join('')}</div></div><div class="hero-account"><div><div class="hero-number">${C.usd(a?.value)} <small>USD</small></div><div class="hero-change"><span class="${tone(a?.netMtd)}">${C.signed(a?.netMtd)}</span> <span style="margin-left:6px">net change · source window</span></div></div><span class="pill ${s?.mode==='DEMO'?'amber':''}">${s?.mode==='DEMO'?'ILLUSTRATIVE':s?.provenance?.reconciliation||'NO SOURCE'}</span></div>${plot()}<div class="chart-meta"><span><i class="legend-dot"></i>Marked account value</span><span>${s?.mode==='DEMO'?'Synthetic series · zero external flows':'Source-defined valuation basis'}</span></div><div class="allocation-strip"><div><span class="label">Cash balance</span><div class="value">${C.usd(a?.cash)}</div></div><div><span class="label">Marked positions</span><div class="value">${C.usd(a?.positionValue)}</div></div><div><span class="label">Reserved in cash</span><div class="value">${C.usd(a?.reserved)}</div></div></div></section>`;}
function enginePanel(){const s=current(),p=s?.pipeline;return `<section class="panel"><div class="panel-head"><h2>Decision engine</h2>${pill(s?.engine?.mode||'NOT CONNECTED','blue')}</div><div class="panel-body"><div class="status-block"><div class="flex"><div class="node-icon">${icon('models',21)}</div><div><h3>BETTOR EV Core</h3><p>Observe. Evaluate. Protect.</p></div></div>${icon('activity',23)}</div><div class="engine-track">${[['eye','OBSERVE'],['models','PRICE'],['risk','GATE'],['lock','ROUTE']].map(([i,label],n)=>`${n?'<span class="connector"></span>':''}<div class="engine-node"><div class="circle">${icon(i,13)}</div><span>${label}</span></div>`).join('')}</div><div class="engine-counters"><div><span class="label">States evaluated</span><b>${C.count(p?.observed)}</b></div><div><span class="label">Rejected</span><b>${C.count(p?.rejected)}</b></div><div><span class="label">Further review</span><b>${C.count(p?.reviewed)}</b></div><div><span class="label">Shadow candidates</span><b class="blue">${C.count(p?.shadow)}</b></div></div><div class="gate-warning">${icon('lock',13)}<span><strong>Decision-grade execution blocked.</strong><br>Fill quantity and joint execution calibration are required. No order is sent by this hub.</span></div></div><div class="panel-footer"><span>Research telemetry ≠ execution authority</span><button class="text-button" data-view="models">Inspect ${icon('arrow',11)}</button></div></section>`;}
function positionTable(limit=Infinity){const s=current();let rows=s?.positions||[];if(S.query){const q=S.query.toLowerCase();rows=rows.filter(p=>`${p.title} ${p.outcome} ${p.venue}`.toLowerCase().includes(q));}if(S.filter!=='ALL')rows=rows.filter(p=>p.sport===S.filter);rows=rows.slice(0,limit);return `<section class="panel"><div class="panel-head"><div><h2>Open positions <span class="count-chip">${s?s.positions.length:'—'}</span></h2><div class="panel-sub">Current marks and the system’s intended next action</div></div>${limit<Infinity?'<button class="text-button" data-view="portfolio">View all '+icon('arrow',12)+'</button>':''}</div>${rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Market / outcome</th><th class="num">Entry / mark</th><th class="num">Value</th><th class="num">Unrl P&L</th><th>System intent</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr data-detail="position" data-id="${C.esc(p.id)}" tabindex="0" role="button" aria-label="Inspect ${C.esc(p.title)}"><td><div class="market-cell"><span class="sport-mark ${p.sport.toLowerCase()}">${C.esc(p.sport==='Soccer'?'SOC':p.sport)}</span><div><span class="market-title">${C.esc(p.title)}</span><span class="market-sub">${C.esc(p.outcome)} · ${C.esc(p.venue)}</span></div></div></td><td class="num"><span class="muted">${C.price(p.entry)}</span> <span style="color:#536c8b">/</span> ${C.price(p.mark)}</td><td class="num">${C.usd(p.value)}</td><td class="num ${tone(p.unrealized)}">${C.signed(p.unrealized)}</td><td>${pill(p.intent,stateTone(p.intent))}</td><td class="row-chevron">${icon('chevron',12)}</td></tr>`).join('')}</tbody></table></div>`:noRows(s?'No matching position records.':'Position data is unavailable; connect a source.')}<div class="panel-footer"><span>${s?.mode==='DEMO'?'Synthetic bid-side marks · USD':'Source-supplied valuation · USD'}</span><span>Intent is informational</span></div></section>`;}
function decisionPanel(){const s=current(),rows=(s?.decisions||[]).slice(0,3);return `<section class="panel"><div class="panel-head"><h2>What the engine sees</h2><button class="text-button" data-view="decisions">All decisions ${icon('arrow',11)}</button></div><div class="decision-list">${rows.length?rows.map(d=>`<div class="decision-card"><button data-detail="decision" data-id="${C.esc(d.id)}"><div class="flex between"><span class="title">${C.esc(d.title)}</span><span class="edge ${tone(d.netEv)}">${C.finite(d.netEv)?(d.netEv>0?'+':'−')+C.price(Math.abs(d.netEv)):'—'}</span></div><div class="flex between"><span class="sub">${C.esc(d.outcome)}</span><span class="sub">estimated / share</span></div><div class="flex between" style="margin-top:8px">${pill(d.state,stateTone(d.state))}<span class="action">${C.esc(d.action)}</span></div></button></div>`).join(''):noRows('No eligible engine telemetry connected.')}</div><div class="panel-footer"><span>Click a decision to inspect the reasoning</span></div></section>`;}
function activityItems(rows){return rows.map(a=>`<div class="activity-item"><span class="activity-glyph">${icon(a.kind==='rejected'?'close':a.kind==='risk'?'shield':a.kind==='order'?'orders':a.kind==='report'?'file':'bolt',11)}</span><div><div class="title">${C.esc(a.title)}</div><div class="detail">${C.esc(a.detail)}</div></div><time>${C.clock(a.at)}</time></div>`).join('');}
function activityPanel(){const s=current();return `<section class="panel"><div class="panel-head"><h2>Activity stream</h2>${S.mode==='demo'?`<button class="text-button" data-action="playback">${icon(S.playback?'pause':'play',12)} ${S.playback?'Pause demo':'Play demo'}</button>`:pill('READ ONLY')}</div><div class="activity-items" id="activity-items">${s?.activity?.length?activityItems(s.activity.slice(0,4)):noRows('Awaiting recorded system events.')}</div><div class="panel-footer"><span id="playback-caption">${S.mode==='demo'?'Fixed synthetic event sequence':'Recorded source events; not browser heartbeat'}</span><span>UTC</span></div></section>`;}
function overview(){return heading('Command overview','Every position. Every decision. One clear view.')+(window.BTMotion?BTMotion.hero({mode:S.mode,connected:!!current()}):'')+kpis()+(window.BTMotion?BTMotion.pulseStrip(current()):'')+(!current()?empty():'')+`<div class="main-grid" style="${!current()?'margin-top:18px':''}"><div>${portfolioChart()}${positionTable(5)}<section class="panel"><div class="panel-head"><h2>Source coverage</h2><button class="text-button" data-action="connection">Inspect connections ${icon('arrow',11)}</button></div><div class="panel-body">${services()}</div><div class="panel-footer"><span>Source timestamps—not browser heartbeats—determine freshness.</span></div></section></div><div class="right-column">${enginePanel()}${decisionPanel()}${activityPanel()}</div></div>`;}
function filters(kind){return `<div class="filters"><div class="filter-input">${icon('search',14)}<input id="table-search" aria-label="Search ${kind}" placeholder="Search markets, outcomes, venues…" value="${C.esc(S.query)}"></div><select id="table-filter" aria-label="${kind==='positions'?'Sport':'Status'} filter">${(kind==='positions'?['ALL','MLB','NFL','Soccer']:kind==='orders'?['ALL','RESTING','PARTIAL','FILLED']:['ALL','SHADOW','WATCHING','REJECTED']).map(v=>`<option value="${v}" ${S.filter===v?'selected':''}>${v==='ALL'?'All '+(kind==='positions'?'sports':'statuses'):v}</option>`).join('')}</select>${btn('Export CSV','csv','download','ghost small',!current()?'disabled':'')}<span class="grow"></span><span class="reporting-label">${current()?.mode==='DEMO'?'ILLUSTRATIVE':'SOURCE SNAPSHOT'}</span></div>`;}
function portfolioPage(){return heading('Portfolio','Positions, marks and capital—without combining unlike records.')+kpis()+filters('positions')+`<div id="filtered-content">${positionTable()}</div><div class="note-block">${icon('info',12)} <strong>Accounting scope.</strong> ${C.esc(current()?.provenance?.accountingBasis||'No source accounting basis supplied.')} Standing buy commitments reserve cash; they are not added to account value. No token NAV or audited-return claim is inferred.</div>`;}
function ordersTable(){let rows=current()?.orders||[];if(S.filter!=='ALL')rows=rows.filter(o=>o.status===S.filter);if(S.query)rows=rows.filter(o=>`${o.title} ${o.id} ${o.venue}`.toLowerCase().includes(S.query.toLowerCase()));return `<section class="panel"><div class="panel-head"><h2>Order blotter</h2><span class="panel-sub">Read-only · no cancellation endpoint</span></div>${rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Order / market</th><th>Venue</th><th>Side</th><th class="num">Limit</th><th>Filled / quantity</th><th>Status</th><th>Placed · UTC</th><th></th></tr></thead><tbody>${rows.map(o=>`<tr data-detail="order" data-id="${C.esc(o.id)}" tabindex="0" role="button" aria-label="Inspect order ${C.esc(o.id)}"><td><span class="market-title">${C.esc(o.title)}</span><span class="market-sub mono">${C.esc(o.id)}</span></td><td class="soft">${C.esc(o.venue)}</td><td><span class="pill ${o.side==='BUY'?'blue':'purple'}">${o.side}</span></td><td class="num">${C.price(o.price)}</td><td><div class="order-fill"><span class="mono">${C.count(o.filled)} / ${C.count(o.quantity)}</span><span class="progress"><i style="width:${o.quantity?o.filled/o.quantity*100:0}%"></i></span></div></td><td>${pill(o.status,stateTone(o.status))}</td><td class="mono muted">${C.clock(o.at)}</td><td class="row-chevron">${icon('chevron',12)}</td></tr>`).join('')}</tbody></table></div>`:noRows('No matching order records.')}<div class="panel-footer"><span>Venue acknowledgments and fills remain separate lifecycle states.</span><span>${rows.length} displayed</span></div></section>`;}
function ordersPage(){return heading('Orders & execution','From order intent to final fill. Nothing hidden between the two.')+filters('orders')+`<div id="filtered-content">${ordersTable()}</div><div class="note-block">This screen observes standing orders; it cannot submit, cancel, or amend them. A partial fill is not a complete fill. A missing order feed is not evidence that no orders exist.</div>`;}
function decisionsTable(){let rows=current()?.decisions||[];if(S.filter!=='ALL')rows=rows.filter(d=>d.state===S.filter);if(S.query)rows=rows.filter(d=>`${d.title} ${d.outcome} ${d.action}`.toLowerCase().includes(S.query.toLowerCase()));return `<section class="panel"><div class="panel-head"><div><h2>Decision field</h2><div class="panel-sub">Estimated values · not production trading recommendations</div></div>${pill('DECISION GRADE BLOCKED','amber')}</div>${rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Candidate</th><th>Proposed action</th><th class="num">Mean EV / share</th><th class="num">P10 / share</th><th class="num">P(EV > 0)</th><th>State</th><th></th></tr></thead><tbody>${rows.map(d=>`<tr data-detail="decision" data-id="${C.esc(d.id)}" tabindex="0" role="button" aria-label="Inspect ${C.esc(d.title)} decision"><td><span class="market-title">${C.esc(d.title)}</span><span class="market-sub">${C.esc(d.outcome)} · ${C.esc(d.family)}</span></td><td class="mono blue">${C.esc(d.action)}</td><td class="num ${tone(d.netEv)}">${C.finite(d.netEv)?(d.netEv>0?'+':'−')+C.price(Math.abs(d.netEv)):'—'}</td><td class="num ${tone(d.p10)}">${C.finite(d.p10)?(d.p10>0?'+':'−')+C.price(Math.abs(d.p10)):'—'}</td><td class="num">${C.pct(d.pPositive,0)}</td><td>${pill(d.state,stateTone(d.state))}</td><td class="row-chevron">${icon('chevron',12)}</td></tr>`).join('')}</tbody></table></div>`:noRows('Decision telemetry is not connected for this audience.')}<div class="table-caption">Missing economic inputs display “—”. No fill estimate is inferred from book movement. ${current()?.mode==='DEMO'?'All probability and EV numbers shown here are synthetic design examples.':''}</div></section>`;}
function decisionsPage(){const p=current()?.pipeline;return heading('EV decision intelligence','See the proposal, the uncertainty, and the reason to say no.')+(window.BTMotion?BTMotion.decisionMap(current()):'')+`<div class="metric-row"><div class="panel"><h3>States evaluated · source window</h3><strong>${C.count(p?.observed)}</strong></div><div class="panel"><h3>Rejection discipline</h3><strong>${p?.observed?C.pct(p.rejected/p.observed,2):'—'}</strong></div><div class="panel"><h3>Live orders sent by this hub</h3><strong>0 <span style="font:11px var(--sans);color:var(--muted)">by design</span></strong></div></div>`+filters('decisions')+`<div id="filtered-content">${decisionsTable()}</div>`;}
function gates(){return `<div class="gate-list">${(current()?.gates||[]).map(g=>`<div class="gate"><span class="${g.status==='PASS'?'positive':'amber'}">${icon(g.status==='PASS'?'check':'lock',15)}</span><div><h3>${C.esc(g.name)}</h3><p>${C.esc(g.detail)}</p></div>${pill(g.status,stateTone(g.status))}</div>`).join('')||noRows('No verified gate results supplied.')}</div>`;}
function exposureRows(key){const s=current();if(!s)return noRows('No exposure data.');const groups=s.audience==='INVESTOR'?(s.allocation||[]):C.marketExposure(s,key);const total=groups.reduce((a,g)=>a+g.value,0);return groups.map((g,i)=>`<div class="allocation-row"><div class="flex between"><span>${C.esc(g.name)}</span><span class="mono">${C.usd(g.value)} <span class="muted">/ ${total?C.pct(g.value/total,1):'—'}</span></span></div><div class="progress"><i style="width:${total?g.value/total*100:0}%;background:${['#498dff','#54bca8','#a395e8','#dba66f'][i%4]}"></i></div></div>`).join('')||noRows('No classified exposure supplied.');}
function riskPage(){const s=current(),cost=s?.positions?.length&&s.positions.every(p=>C.finite(p.cost))?C.sum(s.positions,p=>p.cost):null;return heading('Risk & capital oversight','Exposure belongs to an event—not to a row in a blotter.')+`<div class="main-grid"><div><section class="panel"><div class="panel-head"><h2>Open long-position cost</h2>${pill('NOT VaR')}</div><div class="panel-body"><div class="risk-big">${C.usd(cost)}</div><p class="muted" style="font-size:11px">Cost basis of the displayed long positions. Not a complete account stress-loss calculation.</p></div><div class="value-strip"><div><span class="label">Independent event IDs</span><b>${s?new Set(s.positions.map(p=>p.eventId)).size:'—'}</b></div><div><span class="label">Reserved / cash</span><b>${s?.account?.cash?C.pct(s.account.reserved/s.account.cash,2):'—'}</b></div></div></section><section class="panel"><div class="panel-head"><h2>Event concentration</h2><span class="panel-sub">Position cost · not statistical independence</span></div><div class="panel-body">${exposureRows('title')}</div></section></div><div class="right-column"><section class="panel"><div class="panel-head"><h2>Exposure by sport</h2></div><div class="panel-body">${exposureRows('sport')}</div></section><section class="panel"><div class="panel-head"><h2>Execution readiness</h2>${pill('BLOCKED','amber')}</div>${gates()}</section><section class="panel"><div class="panel-head"><h2>Risk-policy authority</h2>${icon('lock',16)}</div><div class="panel-body"><p class="muted" style="font-size:11px;line-height:1.9">Trading limits, loss controls and emergency stops belong in the independent server-side risk system. This frontend cannot change limits or activate trading.</p></div></section></div></div>`;}
function modelsPage(){return heading('Intelligence & learning','Specialist models. Visible evidence. Controlled promotion.')+`<div class="main-grid"><div><div class="model-grid">${(current()?.models||[]).map(m=>`<section class="model-card"><div class="flex between"><span class="label">${C.esc(m.kind)}</span>${icon('models',17)}</div><h3>${C.esc(m.name)}</h3><p>${C.esc(m.detail)}</p><div style="margin-top:15px">${pill(m.status,m.status==='NOT IDENTIFIED'?'amber':'blue')}</div></section>`).join('')||empty('Model telemetry is not connected','Registry versions, challenger results and promotion evidence appear only when an authorized read-only model feed provides them.')}</div><div class="note-block"><strong>Learning and deployment are different permissions.</strong> The workspace displays evidence and version history. It cannot train models, promote a challenger, manufacture a posterior, or mutate production weights.</div></div><div class="right-column">${enginePanel()}<section class="panel"><div class="panel-head"><h2>Data services</h2>${icon('activity',15)}</div><div class="panel-body">${services()}</div></section></div></div>`;}
function services(){return (current()?.services||[]).map(s=>`<div class="service-row"><span class="service-icon">${icon('globe',16)}</span><div><h3>${C.esc(s.name)}</h3><p>${C.esc(s.detail)}</p></div>${pill(s.status,s.status==='DEMO'?'amber':'')}</div>`).join('')||noRows('No service telemetry available.');}
function reportsPage(){const documents=[['Management overview','The account, portfolio marks, execution context and governance evidence in one branded snapshot.','reports'],['Risk & exposure','Current position detail and readiness controls, with explicit scope and source identification.','risk'],['Investor briefing','A presentation-safe summary with no proprietary decision rows. Distribution still requires approval.','investor']];return heading('Reporting center','Institutional documents, bound to the snapshot they describe.')+`<div class="document-grid">${documents.map(([name,description,i])=>`<section class="document"><div class="doc-preview" aria-hidden="true"><div class="doc-paper"><div class="doc-brand"></div><b>${name.toUpperCase()}</b><span></span><span></span><svg viewBox="0 0 100 25"><path d="M0 23L10 19L18 21L25 16L31 18L43 12L50 15L60 9L70 11L81 5L90 7L100 1" fill="none" stroke="#0066ff" stroke-width="1.4"/></svg><span></span></div></div><div class="doc-body"><div class="flex between"><h2>${name}</h2>${icon(i,17)}</div><p>${description}</p>${btn('Create PDF','report','download','small ghost',`data-kind="${name}" ${!current()?'disabled':''}`)}</div></section>`).join('')}</div><section class="panel" style="margin-top:22px"><div class="panel-head"><h2>This session’s exports</h2><span class="panel-sub">Local browser session · not a server archive</span></div>${S.exports.length?S.exports.map(r=>`<div class="report-meta"><div class="flex">${icon('file',17)}<div>${C.esc(r.kind)}<span class="market-sub mono">${C.esc(r.snapshotId)} · ${C.esc(r.mode)}</span></div></div><div class="flex"><span class="muted mono">${C.clock(r.created)} UTC</span><button class="text-button" data-redownload="${r.id}">Download ${icon('download',12)}</button></div></div>`).join(''):noRows('No PDF reports generated in this browser session.')}</section><div class="note-block"><strong>Report integrity.</strong> Exports include source classification, snapshot time, accounting basis and SHA-256 of the source snapshot. A checksum is not an audit. Demo and shadow reports remain labeled on every page.</div>`;}
function auditPage(){const s=current();return heading('Audit & source lineage','An inspectable record—not an animation standing in for evidence.')+`<div class="main-grid"><div><section class="panel"><div class="panel-head"><h2>Recorded events</h2>${pill(s?.mode==='DEMO'?'DEMO EVENTS':'SOURCE EVENTS',s?.mode==='DEMO'?'amber':'')}</div>${(s?.activity||[]).map(a=>`<div class="audit-row"><time>${C.clock(a.at)}Z</time><div><h3>${C.esc(a.title)}</h3><p>${C.esc(a.detail)}</p><span class="snapshot-hash">${C.esc(a.id)}</span></div>${pill(a.kind.toUpperCase())}</div>`).join('')||noRows('No recorded events supplied.')}<div class="version-line">${icon('lock',12)}This viewer cannot rewrite source records.</div></section></div><div class="right-column"><section class="panel"><div class="panel-head"><h2>Snapshot manifest</h2>${icon('file',15)}</div><div class="panel-body"><div class="detail-list" style="margin:0">${[['Schema',s?.schema],['Snapshot ID',s?.snapshotId],['Mode',s?.mode],['Audience',s?.audience],['As of',s?.asOf],['Source',s?.provenance?.sourceId]].map(([k,v])=>`<div class="row"><span>${k}</span><b style="font-size:9px;max-width:190px;overflow-wrap:anywhere">${C.esc(v||'NOT CONNECTED')}</b></div>`).join('')}</div><div style="margin-top:15px">${btn('Export manifest','manifest','download','small ghost',!s?'disabled':'')}</div></div></section><section class="panel"><div class="panel-head"><h2>Read-only guarantees</h2></div><div class="panel-body"><p class="muted" style="font-size:11px;line-height:1.9">No venue credentials. No trade endpoints. No hidden demo fallback. Stale or disconnected data stays labeled. The operating engine and frozen capture remain outside this application.</p></div></section></div></div>`;}
function investorPage(){const s=current();if(!s)return heading('Investor briefing','A controlled view of the platform, supported by source records.')+empty('Investor data is not connected','Live investor presentation requires a server-authorized, redacted projection. Switching a browser tab is not access control. The design preview contains synthetic data only.');return `<div class="investor-hero"><img class="investor-brand" src="${C.esc(cfg.logo)}" alt="Bettor Token"><div class="label">INSTITUTIONAL OVERSIGHT / ${s.mode==='DEMO'?'DESIGN PREVIEW':'READ-ONLY PROJECTION'}</div><h1>The discipline is the edge.</h1><p>One view of the account, the capital at work and the controls behind each decision. Designed for transparency—not a black box.</p>${btn('Export investor briefing','report','download','primary','data-kind="Investor briefing"')}</div>${kpis()}<div class="main-grid"><div>${portfolioChart()}<section class="panel"><div class="panel-head"><h2>What these numbers represent</h2></div><div class="panel-body"><p class="muted" style="font-size:12px;line-height:1.9">${C.esc(s.provenance.accountingBasis)}</p><div class="note-block">${s.mode==='DEMO'?'<strong>Demonstration only.</strong> All financial amounts and charts are synthetic. They do not represent BettorToken returns, client assets, a forecast, or an offering.':'Unaudited source records. Portfolio value is not Company or token NAV. Past results do not predict future performance.'}</div></div></section></div><div class="right-column"><section class="panel"><div class="panel-head"><h2>Capital at work</h2></div><div class="panel-body">${exposureRows('sport')}</div></section><section class="panel"><div class="panel-head"><h2>Control framework</h2></div>${gates()}</section><section class="panel"><div class="panel-head"><h2>The BettorToken platform</h2></div><div class="panel-body"><p class="muted" style="font-size:11px;line-height:1.8">Company information and definitive disclosures live on the BettorToken website. This workspace does not substitute for offering documents or investor statements.</p><a class="text-button" style="margin-top:13px" href="https://bettortoken.com/" target="_blank" rel="noopener noreferrer">BettorToken.com ${icon('external',12)}</a></div></section></div></div>`;}
function viewContent(){return ({command:overview,portfolio:portfolioPage,orders:ordersPage,decisions:decisionsPage,risk:riskPage,models:modelsPage,reports:reportsPage,audit:auditPage,investor:investorPage}[S.view]||overview)();}
function updateClock(){const el=document.getElementById('top-clock');if(el)el.textContent=new Date().toISOString().slice(11,19)+' UTC';const badge=document.getElementById('source-badge');if(badge)badge.innerHTML=sourceBadge();}
function bindChart(){const wrap=document.querySelector('[data-chart="portfolio"]');if(!wrap)return;wrap.querySelectorAll('.chart-hit').forEach(point=>{point.addEventListener('pointerenter',()=>{const tip=document.getElementById('chart-tooltip');tip.textContent=C.usd(Number(point.dataset.value))+' · '+C.date(point.dataset.at);tip.style.display='block';const r=point.getBoundingClientRect(),w=wrap.getBoundingClientRect();tip.style.left=Math.min(Math.max(r.left-w.left-50,0),Math.max(0,w.width-220))+'px';tip.style.top=Math.max(0,r.top-w.top-36)+'px';});point.addEventListener('pointerleave',()=>{document.getElementById('chart-tooltip').style.display='none';});});}
function setView(v){if(!nav.some(n=>n[0]===v))v='command';const old=S.view;S.view=v;S.query='';S.filter='ALL';S.menu=false;closeOverlay();if(location.hash.slice(1)!==v)history.replaceState(null,'','#'+v);if(S.mode==='connected'&&(old==='investor')!==(v==='investor')){S.snapshot=null;S.pending=null;S.frozen=false;S.exports=[];feed.start(v==='investor'?'INVESTOR':'INTERNAL');}render();window.scrollTo(0,0);}
function setDemo(){feed.stop();S.mode='demo';S.snapshot=C.demoSnapshot();S.connection='disconnected';S.error=null;S.frozen=false;S.pending=null;S.step=0;S.exports=[];S.playback=false;closeOverlay();render();}
function exitDemo(){feed.stop();S.mode='offline';S.snapshot=null;S.error=null;S.playback=false;S.frozen=false;S.exports=[];closeOverlay();render();}
function openOverlay(content,drawer=false){S.lastFocus=document.activeElement;overlayRoot.innerHTML=`<div class="overlay ${drawer?'drawer-overlay':''}" data-backdrop="true"><div class="${drawer?'drawer':'modal'}" role="dialog" aria-modal="true" aria-label="${drawer?'Record details':'Workspace dialog'}">${content}</div></div>`;document.body.style.overflow='hidden';const f=overlayRoot.querySelector('input,select,button,a,[tabindex]');setTimeout(()=>f?.focus(),0);}
function closeOverlay(){overlayRoot.innerHTML='';document.body.style.overflow='';S.lastFocus?.focus?.();}
function detailRow(k,v){return `<div class="row"><span>${C.esc(k)}</span><b>${C.esc(v)}</b></div>`;}
function drawer(kind,id){const s=current();if(!s)return;const row=(kind==='position'?s.positions:kind==='order'?s.orders:s.decisions).find(r=>r.id===id);if(!row)return;let body='';const badge=pill(s.mode==='DEMO'?'ILLUSTRATIVE RECORD':s.mode,s.mode==='DEMO'?'amber':'blue');if(kind==='position'){const age=(Date.parse(s.asOf)-Date.parse(row.openedAt))/1000;body=`${badge}<div class="drawer-heading"><h2>${C.esc(row.title)}</h2><p>${C.esc(row.outcome)} · ${C.esc(row.venue)}</p></div><div class="drawer-metrics"><div><span class="label">Marked value</span><div class="v">${C.usd(row.value)}</div></div><div><span class="label">Unrealized P&L</span><div class="v ${tone(row.unrealized)}">${C.signed(row.unrealized)}</div></div></div><div class="detail-list">${detailRow('Held quantity',C.count(row.quantity)+' shares')}${detailRow('Leg / outcome',row.leg)}${detailRow('Average entry',C.price(row.entry))}${detailRow('Current mark',C.price(row.mark))}${detailRow('Cost basis',C.usd(row.cost))}${detailRow('Time held',C.duration(age))}${detailRow('Mark basis',row.markBasis)}${detailRow('As of',row.asOf)}</div><div class="drawer-callout"><div class="flex between"><h3>System intent</h3>${pill(row.intent,stateTone(row.intent))}</div><p>${C.esc(row.reason)}</p></div><div class="label" style="margin-top:24px">Related standing orders</div>${s.orders.filter(o=>o.positionId===id&&o.status!=='FILLED').map(o=>`<button class="selectable-row" style="padding:13px 0;border-bottom:1px solid var(--line)" data-detail="order" data-id="${C.esc(o.id)}"><div class="flex between"><span class="mono" style="font-size:10px">${C.esc(o.id)}</span>${pill(o.status,stateTone(o.status))}</div><div class="market-sub">${o.side} ${C.count(o.quantity)} @ ${C.price(o.price)}</div></button>`).join('')||'<p class="muted" style="font-size:11px;margin-top:12px">No linked standing order in this snapshot.</p>'}<div class="snapshot-hash" style="margin-top:20px">${C.esc(row.marketId)}<br>${C.esc(row.eventId)}</div>`;}
 else if(kind==='order'){body=`${badge}<div class="drawer-heading"><h2>${C.esc(row.title)}</h2><p>${C.esc(row.outcome)} · ${C.esc(row.venue)}</p></div><div class="drawer-metrics"><div><span class="label">Limit price</span><div class="v">${C.price(row.price)}</div></div><div><span class="label">Fill completion</span><div class="v">${row.quantity?C.pct(row.filled/row.quantity,1):'—'}</div></div></div><div class="detail-list">${detailRow('Order ID',row.id)}${detailRow('Side',row.side)}${detailRow('Quantity',C.count(row.quantity))}${detailRow('Filled quantity',C.count(row.filled))}${detailRow('Remaining quantity',C.count(row.quantity-row.filled))}${detailRow('Status',row.status)}${detailRow('Placed at',row.at)}</div><div class="label">Lifecycle ${s.mode==='DEMO'?'example':''}</div><div class="timeline"><div class="point"><h3>Order intention recorded</h3><p>${C.clock(row.at)} UTC</p></div><div class="point"><h3>Venue acknowledgment</h3><p>${s.mode==='DEMO'?'SIMULATED ACKNOWLEDGMENT':'See source order log for exact ACK time'}</p></div><div class="point"><h3>${row.status==='PARTIAL'?'Partial fill recorded':row.status==='FILLED'?'Fill complete':'Resting at the venue'}</h3><p>${C.count(row.filled)} / ${C.count(row.quantity)} shares</p></div></div><div class="notice-mini">This view cannot cancel or modify an order. ${s.mode==='DEMO'?'This entire lifecycle is synthetic.':'Use separately authorized execution tooling for any action.'}</div>`;}
 else {const pts=Array.from({length:61},(_,i)=>{const x=12+i*6.2;const y=118-Math.exp(-Math.pow((i-30)/13,2)/2)*85;return `${i?'L':'M'}${x.toFixed(1)},${y.toFixed(1)}`;}).join(' ');body=`${badge}<div class="drawer-heading"><h2>${C.esc(row.title)}</h2><p>${C.esc(row.outcome)} · ${C.esc(row.family)}</p></div><div class="drawer-metrics"><div><span class="label">Estimated mean EV</span><div class="v ${tone(row.netEv)}">${C.finite(row.netEv)?(row.netEv>0?'+':'−')+C.price(Math.abs(row.netEv)):'—'}</div><span class="muted" style="font-size:9px">USD / posted share</span></div><div><span class="label">P(EV &gt; 0)</span><div class="v">${C.pct(row.pPositive,0)}</div><span class="muted" style="font-size:9px">Not probability of profit</span></div></div><div class="label">Illustrative uncertainty visualization</div><div class="distribution"><svg viewBox="0 0 400 150" aria-label="Schematic distribution; not reconstructed from quantiles"><defs><linearGradient id="dist-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#398cff" stop-opacity=".4"/><stop offset="100%" stop-color="#398cff" stop-opacity=".02"/></linearGradient></defs><path d="${pts} L384,120 L12,120Z" fill="url(#dist-fill)"/><path d="${pts}" fill="none" stroke="#4e9cff" stroke-width="2"/><line x1="112" y1="18" x2="112" y2="125" stroke="#d49d67" stroke-dasharray="3 4"/><text x="108" y="142" fill="#a58e78" font-size="9">zero</text></svg></div><div class="dist-stats"><span>P10 ${C.price(row.p10)}</span><span>MEAN ${C.price(row.netEv)}</span><span>P90 ${C.price(row.p90)}</span></div><div class="detail-list">${detailRow('Candidate action',row.action)}${detailRow('Quote price',C.price(row.price))}${detailRow('Illustrative size',C.count(row.quantity)+' shares')}${detailRow('Native fill probability',C.pct(row.fillProbability))}${detailRow('Decision-grade EV',row.gate)}${detailRow('Evidence classification',row.evidence)}</div><div class="drawer-callout"><div class="flex between"><h3>Why this action is being considered</h3>${icon('models',16)}</div><p>${C.esc(row.reason)}</p></div><div class="gate-warning">${icon('lock',15)}<span><strong>${C.esc(row.blocker)}</strong><br>Not an executable recommendation. No order has been authorized.</span></div><div class="snapshot-hash" style="margin-top:18px">${C.esc(row.id)} · ${C.clock(row.at)}Z</div>`;}
 openOverlay(`<div class="drawer-top"><h2>${kind==='position'?'Position intelligence':kind==='order'?'Order lifecycle':'Decision receipt'}</h2><button class="icon-button" data-action="close" aria-label="Close detail">${icon('close',18)}</button></div><div class="drawer-content">${body}<div class="note-block">${icon('lock',12)} Read-only observation · never a trading control.</div></div>`,true);
}
function connectionModal(){openOverlay(`<div class="modal-head"><h2>Read-only data connection</h2><button class="icon-button" data-action="close" aria-label="Close connection settings">${icon('close',18)}</button></div><div class="modal-body"><p>The interface is ready for a server-owned aggregation endpoint. It does not connect directly to venues and never accepts trading credentials.</p><span class="label">Internal snapshot endpoint</span><div class="integration-field">${C.esc(cfg.snapshot)}</div><span class="label">Investor projection endpoint</span><div class="integration-field">${C.esc(cfg.investorSnapshot)}</div><div class="notice-mini"><strong>Backend integration required.</strong> These are new read-only contracts, not assumed existing routes. The host must enforce authentication, role-specific projections, freshness, and authorization. The frontend cannot supply that security.</div><div class="detail-list">${detailRow('Current connection',S.connection)}${detailRow('Display mode',S.mode)}${detailRow('Source snapshot',S.snapshot?.snapshotId||'Unavailable')}${detailRow('As of',S.snapshot?.asOf||'Unavailable')}${detailRow('Trading authority','NONE')}</div></div><div class="modal-footer">${btn('Stay offline','close',null,'ghost')}${btn('Connect read-only feed','connect','link','primary')}</div>`);}
function reportModal(kind){if(!current()){connectionModal();return;}kind=kind||'Management overview';openOverlay(`<div class="modal-head"><h2>Generate a branded PDF</h2><button class="icon-button" data-action="close" aria-label="Close report dialog">${icon('close',18)}</button></div><div class="modal-body"><p>Create an actual PDF from one frozen copy of this snapshot. Labels and source identity travel with the numbers.</p><div class="field"><label for="report-kind">Report</label><select id="report-kind">${['Management overview','Risk & exposure','Investor briefing'].map(k=>`<option ${k===kind?'selected':''}>${k}</option>`).join('')}</select></div><div class="detail-list">${detailRow('Source mode',current().mode)}${detailRow('Snapshot',current().snapshotId)}${detailRow('Data as of',current().asOf)}</div><div class="notice-mini">${current().mode==='DEMO'?'<strong>DEMONSTRATION ONLY.</strong> The PDF will be watermarked as illustrative and must not be represented as BettorToken performance.':'Exports are unaudited snapshots. Investor reports require the server-authorized investor projection, not client-side hiding of confidential data.'}</div></div><div class="modal-footer">${btn('Cancel','close',null,'ghost')}${btn('Generate PDF','generatePdf','download','primary')}</div>`);}
async function generatePdf(){const button=overlayRoot.querySelector('[data-action="generatePdf"]');const kind=document.getElementById('report-kind')?.value||'Management overview';let s=current();if(!s)return;if(kind==='Investor briefing'&&s.audience!=='INVESTOR'){if(s.mode==='DEMO')s=C.projectInvestor(s);else{toast('Use the server-authorized Investor briefing view first.');return;}}if(button){button.disabled=true;button.textContent='Creating PDF…';}try{const r=await window.BTReport.create(s,kind);window.BTReport.save(r.blob,r.filename);S.exports.unshift({id:'report-'+Date.now(),kind,blob:r.blob,filename:r.filename,created:r.created,mode:r.snapshot.mode,snapshotId:r.snapshot.snapshotId,hash:r.hash});closeOverlay();toast(`${r.pages}-page ${r.snapshot.mode==='DEMO'?'demo ':''}PDF created.`);if(S.view==='reports')render();}catch(e){toast('Report unavailable: '+e.message);if(button){button.disabled=false;button.textContent='Generate PDF';}}}
function searchModal(){openOverlay(`<div class="palette-input">${icon('search',21)}<input id="command-search" placeholder="Search pages, positions, decisions…" aria-label="Workspace search"><button class="icon-button" data-action="close" aria-label="Close search">${icon('close',16)}</button></div><div class="palette-results" id="palette-results"></div><div class="search-foot">ENTER selects the first result · ESC closes · Read-only workspace</div>`);overlayRoot.querySelector('.modal').classList.add('search-modal');paletteResults('');}
function paletteResults(q){const k=q.toLowerCase();const results=[];nav.filter(([id,label])=>label.toLowerCase().includes(k)).forEach(([id,label])=>results.push(`<button class="palette-item" data-view="${id}">${icon(id,17)}${label}<small>PAGE</small>${icon('arrow',11)}</button>`));if(current()?.audience!=='INVESTOR'){(current()?.positions||[]).filter(p=>`${p.title} ${p.outcome}`.toLowerCase().includes(k)).slice(0,5).forEach(p=>results.push(`<button class="palette-item" data-detail="position" data-id="${C.esc(p.id)}">${icon('portfolio',17)}${C.esc(p.title)}<small>POSITION</small>${icon('arrow',11)}</button>`));}(document.getElementById('palette-results')||{}).innerHTML=results.join('')||'<div class="empty"><p>No matching records.</p></div>';}
function infoModal(type){let title='Read-only workspace',body='<p>You are using an observation interface. It has no venue credentials, order submission, cash-out, cancellation, limit editing or production-promotion capability.</p><div class="notice-mini">Investor presentation is a separate data projection. A visual mode switch is not an authentication or authorization boundary.</div>';if(type==='alerts'){title='System notifications';body=`<p>Readiness results below are ${current()?.mode==='DEMO'?'synthetic examples':'supplied by the source'}. The interface does not execute remedial actions.</p>${gates()}`;}if(type==='source'){title='Source & freshness';const s=current();body=`<p>${C.esc(s?.provenance?.accountingBasis||'No accounting snapshot is connected.')}</p><div class="detail-list">${detailRow('Mode',s?.mode||'DISCONNECTED')}${detailRow('Source ID',s?.provenance?.sourceId||'Not provided')}${detailRow('As of',s?.asOf||'Not provided')}${detailRow('Sequence',s?.sequence??'Not provided')}${detailRow('Reporting window',s?.provenance?.window||'Not provided')}</div><div class="notice-mini">The top UTC clock is the browser clock. It does not prove that any market, position, or order data is fresh.</div>`;}openOverlay(`<div class="modal-head"><h2>${title}</h2><button class="icon-button" data-action="close" aria-label="Close information">${icon('close',18)}</button></div><div class="modal-body">${body}</div><div class="modal-footer">${btn('Done','close',null,'primary')}</div>`);}
async function manifest(){if(!current())return;const s=C.clone(current());const hash=await C.digest(s);window.BTReport.save(new Blob([JSON.stringify({exportSchema:'bt.command.export.v1',createdAt:new Date().toISOString(),snapshotSha256:hash,integrityOnly:true,snapshot:s},null,2)],{type:'application/json'}),`BettorToken_${s.mode}_Snapshot_${s.asOf.slice(0,10)}.json`);toast('Source snapshot and digest exported.');}
function csv(){const s=current();if(!s)return;let headers,rows;if(S.view==='orders'){headers=['Mode','Order ID','Market','Venue','Side','Price USD/share','Quantity','Filled','Status','Snapshot as of'];rows=s.orders.map(o=>[s.mode,o.id,o.title,o.venue,o.side,o.price,o.quantity,o.filled,o.status,s.asOf]);}else if(S.view==='decisions'){headers=['Mode','Decision ID','Market','Action','EV USD/posted share','P10','P90','P(EV>0)','Decision-grade','Snapshot as of'];rows=s.decisions.map(d=>[s.mode,d.id,d.title,d.action,d.netEv,d.p10,d.p90,d.pPositive,d.gate,s.asOf]);}else{headers=['Mode','Position ID','Market','Outcome','Venue','Quantity','Entry USD/share','Mark USD/share','Value USD','Unrealized PnL USD','System intent','Snapshot as of'];rows=s.positions.map(p=>[s.mode,p.id,p.title,p.outcome,p.venue,p.quantity,p.entry,p.mark,p.value,p.unrealized,p.intent,s.asOf]);}window.BTReport.save(new Blob(['\uFEFF'+C.toCsv(headers,rows)],{type:'text/csv;charset=utf-8'}),`BettorToken_${s.mode}_${S.view}_${s.asOf.slice(0,10)}.csv`);toast('CSV exported with source mode and snapshot time.');}
function filtered(){const el=document.getElementById('filtered-content');if(!el)return;el.innerHTML=S.view==='orders'?ordersTable():S.view==='decisions'?decisionsTable():positionTable();}
function handleClick(event){const view=event.target.closest('[data-view]');if(view){setView(view.dataset.view);return;}const detail=event.target.closest('[data-detail]');if(detail){drawer(detail.dataset.detail,detail.dataset.id);return;}const period=event.target.closest('[data-period]');if(period){S.period=period.dataset.period;render();return;}const down=event.target.closest('[data-redownload]');if(down){const r=S.exports.find(x=>x.id===down.dataset.redownload);if(r)window.BTReport.save(r.blob,r.filename);return;}const target=event.target.closest('[data-action]');if(!target){if(event.target.dataset.backdrop)closeOverlay();return;}const a=target.dataset.action;
 if(a==='close'){closeOverlay();return;}if(a==='menu'){S.menu=!S.menu;render();return;}if(a==='demo'){closeOverlay();setDemo();return;}if(a==='exitDemo'){exitDemo();return;}if(a==='search'){searchModal();return;}if(a==='connection'){connectionModal();return;}if(a==='connect'){S.mode='connected';S.snapshot=null;S.pending=null;S.frozen=false;S.exports=[];S.playback=false;closeOverlay();feed.start(S.view==='investor'?'INVESTOR':'INTERNAL');render();return;}if(a==='freeze'){if(!S.snapshot)return;S.frozen=!S.frozen;if(!S.frozen&&S.pending){S.snapshot=S.pending;S.pending=null;}render();toast(S.frozen?'Display frozen. Execution is unaffected.':'Display resumed.');return;}if(a==='report'){reportModal(target.dataset.kind);return;}if(a==='generatePdf'){generatePdf();return;}if(a==='csv'){csv();return;}if(a==='manifest'){manifest();return;}if(a==='playback'){S.playback=!S.playback;render();return;}if(['profile','alerts','source'].includes(a)){infoModal(a);return;}}
document.addEventListener('click',handleClick);
document.addEventListener('input',e=>{if(e.target.id==='table-search'){S.query=e.target.value;filtered();}if(e.target.id==='command-search')paletteResults(e.target.value);});
document.addEventListener('change',e=>{if(e.target.id==='table-filter'){S.filter=e.target.value;filtered();}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();searchModal();}if(e.key==='Escape'){closeOverlay();if(S.menu){S.menu=false;render();}}if(e.key==='Enter'&&e.target.closest('[data-detail]')){e.preventDefault();e.target.closest('[data-detail]').click();}if(e.key==='Enter'&&e.target.id==='command-search'){document.querySelector('.palette-item')?.click();}if(e.key==='Tab'&&overlayRoot.firstChild){const f=[...overlayRoot.querySelectorAll('button:not(:disabled),a,input,select,[tabindex="0"]')];if(!f.length)return;const first=f[0],last=f.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('hashchange',()=>setView(location.hash.slice(1)));
setInterval(updateClock,1000);
setInterval(()=>{if(!S.playback||S.mode!=='demo'||document.hidden||S.frozen||S.view==='investor')return;S.step++;const examples=[['decision','Candidate evaluated','Illustrative microstructure state · research only'],['rejected','Candidate rejected','Missing execution evidence · no order sent'],['risk','Risk gate evaluated','No production authorization'],['decision','Exit opportunity under review','Passive-exit comparison · synthetic example']];const e=examples[(S.step-1)%examples.length];const at=new Date(Date.parse('2026-09-17T22:30:00Z')+S.step*5000).toISOString();S.snapshot.asOf=at;S.snapshot.sequence=1+S.step;S.snapshot.snapshotId='DEMO-PLAYBACK-'+S.step;S.snapshot.activity.unshift({id:'demo-play-'+S.step,at,kind:e[0],title:e[1],detail:e[2]});S.snapshot.activity=S.snapshot.activity.slice(0,30);const items=document.getElementById('activity-items');if(items)items.innerHTML=activityItems(S.snapshot.activity.slice(0,4));const caption=document.getElementById('playback-caption');if(caption)caption.textContent='SIMULATED CLOCK · '+C.clock(at)+'Z';},5000);
window.addEventListener('pagehide',()=>feed.stop());
S.view=nav.some(n=>n[0]===location.hash.slice(1))?location.hash.slice(1):'command';
if(new URLSearchParams(location.search).get('demo')==='1'||cfg.defaultDemo)setDemo();else render();
if(cfg.autoConnect&&S.mode!=='demo'){S.mode='connected';feed.start(S.view==='investor'?'INVESTOR':'INTERNAL');}
// Test hook contains only display state; it cannot place trades or promote models.
window.BettorCommand={version:C.VERSION,inspect:()=>({view:S.view,mode:S.mode,connection:S.connection,snapshot:S.snapshot?C.clone(S.snapshot):null}),setDemo,disconnect:exitDemo};
})();
